WITH RECURSIVE subtree (id) AS (
    SELECT id FROM wiki_page_block
    WHERE page_id = #{pageId}
      AND is_deleted = 0
      AND id IN
      #{r}
    UNION ALL
    SELECT c.id FROM wiki_page_block c
    INNER JOIN subtree s ON c.parent_id = s.id
    WHERE c.page_id = #{pageId}
      AND c.is_deleted = 0
)
SELECT id FROM subtree
